        "v": "В вариантном исполнении автомобиль комплектуется передними ремнями безопасности с предварительным натяжителем и ограничителем нагрузки, расположенным в катушках передних ремней безопасности. Устройства натяжения передних ремней безопасности предназначены для дополнительной фиксации водителя и переднего пассажира в сиденье при фронтальном столкновении. Ограничитель нагрузки предназначен для регулировки усилия сжатия ремнем безопасности водителя и переднего пассажира при фронтальном столкновении."
