        "t": "p",
        "v": "СНПБ должна срабатывать при сильных фронтальных ударах. Однако СНПБ может также сработать и в других аварийных ситуациях, если автомобиль будет испытывать воздействия, аналогичные тем, которым он подвергается при сильном фронтальном ударе. Примеры ситуаций со срабатыванием СНПБ (рис. 24):"
