        "t": "p",
        "v": "19 — сигнализатор разряда аккумуляторной батареи. Загорается красным светом при включении зажигания и после запуска двигателя гаснет.\nЕсли сигнализатор не загорается, включается (в вариантном исполнении) прерывистый сигнал зуммера (выключается через 30 секунд или после выключения зажигания).\nОбязательно контролируйте загорание сигнализатора при включении зажигания! Если сигнализатор не загорается, это указывает на неисправность системы зарядки аккумулятора или повреждение самого сигнализатора. При работающем двигателе загорание сигнализатора, сопровождаемое прерывистым (5 кратковременных включений) сигналом зуммера, может указывать на слабое натяжение или обрыв ремня привода генератора или неисправность самого генератора."
