        "v": "Заводские значения расхода топлива, приводимые в спецификациях, получены в лабораторных условиях по методикам ЕЭК ООН №101 (ГОСТ Р 41.101) и служат для сравнения автомобилей разных производителей. Эксплуатационный расход может существенно отличаться от заявленного из-за множества факторов."
